import numpy as np

def predict(x, theta):
    x = np.asarray(x, dtype=float)
    theta = np.asarray(theta, dtype=float)
    if theta.size != x.size + 1:
        raise ValueError('theta must contain weights and bias')
    return float(x @ theta[:-1] + theta[-1])

def central_difference(f, x, h=1e-5):
    if h <= 0:
        raise ValueError('h must be positive')
    return (f(x + h) - f(x - h)) / (2.0 * h)

print(central_difference(lambda t: t**3, 2.0))

import numpy as np

def sensitivity(f, x, h=1e-5):
    return (f(x + h) - f(x - h)) / (2*h)

print(sensitivity(np.sin, 0.3))

def linearize(f, df, x0, x):
    return f(x0) + df(x0) * (x - x0)

f = lambda x: x**2
df = lambda x: 2*x
print(linearize(f, df, 2.0, 2.1), f(2.1))

def partial_x(f, x, y, h=1e-5):
    return (f(x+h, y) - f(x-h, y)) / (2*h)

f = lambda x, y: x**2 + 3*y**2
print(partial_x(f, 1.0, 2.0))

import numpy as np

def directional_derivative(grad, u, eps=1e-12):
    u = np.asarray(u, dtype=float)
    n = np.linalg.norm(u)
    if n < eps:
        raise ValueError('direction must be non-zero')
    return float(np.asarray(grad, dtype=float) @ (u / n))

