import numpy as np

def classify_1d(df, d2f, x, tol=1e-8):
    if abs(df(x)) > tol:
        return 'not stationary'
    curvature = d2f(x)
    return 'local minimum' if curvature > 0 else 'local maximum' if curvature < 0 else 'inconclusive'
